<section class="page-heading"><div><p class="eyebrow">Invigilation masters</p><h1>Faculty directory</h1><p>Maintain active faculty records, schools, designations, and balanced duty counts.</p></div><div class="heading-actions"><a class="secondary-button" href="<?= e(url('faculty/import')) ?>">Import file</a><a class="secondary-button" href="<?= e(url('faculty/availability')) ?>">Availability</a><a class="primary-button" href="<?= e(url('faculty/create')) ?>">Add faculty</a></div></section>
